using System;using System.Collections;using System.Reflection;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
namespace LWS.TruckWaterSports.Tests {
public sealed class WaterPhysicsTests {
 GameObject root;Type vesselType,courseType;Component vessel,course;Rigidbody body;
 static Type Runtime(string name){foreach(var a in AppDomain.CurrentDomain.GetAssemblies()){var t=a.GetType(name);if(t!=null)return t;}throw new InvalidOperationException("Runtime type not loaded: "+name);}
 static void Field(object target,string name,object value)=>target.GetType().GetField(name).SetValue(target,value);
 static object Call(object target,string name,params object[] args)=>target.GetType().GetMethod(name).Invoke(target,args);
 [SetUp]public void Setup(){vesselType=Runtime("LWS.TruckWaterSports.WaterVessel");courseType=Runtime("LWS.TruckWaterSports.WaterCourse");root=new GameObject("Water physics acceptance vessel");body=root.AddComponent<Rigidbody>();body.useGravity=false;body.mass=100;body.angularDamping=0;vessel=root.AddComponent(vesselType);Field(vessel,"body",body);Field(vessel,"paddles",Array.Empty<Transform>());course=root.AddComponent(courseType);Field(course,"stations",new[]{Vector3.zero,new Vector3(0,0,50),new Vector3(25,-5,100)});Field(vessel,"course",course);}
 [TearDown]public void Teardown(){UnityEngine.Object.DestroyImmediate(root);}
 [UnityTest]public IEnumerator EitherCanoeStationAppliesRealImpulse(){Assert.That((bool)Call(vessel,"Stroke",0,1f,1f,0f),Is.True);yield return new WaitForFixedUpdate();float first=body.linearVelocity.z;Assert.That(first,Is.GreaterThan(1));body.linearVelocity=body.angularVelocity=Vector3.zero;Assert.That((bool)Call(vessel,"Stroke",1,1f,2f,0f),Is.True);yield return new WaitForFixedUpdate();Assert.That(body.linearVelocity.z,Is.GreaterThan(1));}
 [UnityTest]public IEnumerator OppositePaddlePositionsTurnInOppositeDirections(){Call(vessel,"Stroke",0,1f,1f,0f);yield return new WaitForFixedUpdate();float left=body.angularVelocity.y;body.linearVelocity=body.angularVelocity=Vector3.zero;Call(vessel,"Stroke",1,1f,2f,0f);yield return new WaitForFixedUpdate();Assert.That(left*body.angularVelocity.y,Is.LessThan(0));}
 [Test]public void StrokeCooldownPreventsRepeatedPhysicsImpulse(){Assert.That((bool)Call(vessel,"Stroke",0,1f,1f,0f),Is.True);Assert.That((bool)Call(vessel,"Stroke",0,1f,1.1f,0f),Is.False);Assert.That((int)vesselType.GetProperty("Strokes").GetValue(vessel),Is.EqualTo(1));}
 [Test]public void SynchronizedStationsAreMeasured(){Call(vessel,"Stroke",0,1f,1f,0f);Call(vessel,"Stroke",1,1f,1.1f,0f);Assert.That((int)vesselType.GetProperty("Synchronizations").GetValue(vessel),Is.EqualTo(1));}
 [Test]public void RiverCurrentFollowsThreeDimensionalCourse(){var current=(Vector3)Call(course,"Current",new Vector3(15,-3,80),0f);Assert.That(current.z,Is.GreaterThan(0));Assert.That(current.y,Is.LessThan(0));}
 [UnityTest]public IEnumerator CurrentMovesTheActualBodyWithoutPaddling(){root.SetActive(false);var flotation=root.AddComponent(Runtime("LWS.TruckSports.SportsFloatingBody"));Field(flotation,"body",body);var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);Field(flotation,"proxy",primitive.GetComponent<MeshFilter>().sharedMesh);UnityEngine.Object.DestroyImmediate(primitive);((Behaviour)flotation).enabled=false;Field(vessel,"flotation",flotation);root.SetActive(true);Call(vessel,"Tick",.02f,1f);yield return new WaitForFixedUpdate();Assert.That(body.linearVelocity.z,Is.GreaterThan(.02f));}
 [Test]public void InvertedHullIsRecognizedAsCapsized(){root.transform.rotation=Quaternion.Euler(0,0,180);Assert.That((bool)vesselType.GetProperty("Capsized").GetValue(vessel),Is.True);root.transform.rotation=Quaternion.identity;Assert.That((bool)vesselType.GetProperty("Capsized").GetValue(vessel),Is.False);}
}
}
